const canvas = document.getElementById("signature");
const ctx = canvas.getContext("2d");
const background = new Image();
background.src = "data:image/png;base64,";
background.onload = draw;
const logo = new Image();
const seal = new Image();
logo.src = "data:image/png;base64,";
seal.src = "data:image/png;base64,";
seal.src = "data:image/png;base64,";
logo.onload = draw;
seal.onload = draw;
logo.onerror = () => console.error("Não foi possível carregar a logo.");
seal.onerror = () => console.error("Não foi possível carregar o selo.");

function get(id) { return document.getElementById(id).value.trim(); }
function fitText(text, maxWidth, startSize, minSize, weight = "normal", family = "Arial") {
    let size = startSize;
    do { ctx.font = `${weight} ${size}px ${family}`; if (ctx.measureText(text).width <= maxWidth) break; size--; } while (size >= minSize);
    return Math.max(size, minSize);
}
function drawIcon(type, x, y) {
    ctx.save(); ctx.fillStyle = "#f58220"; ctx.beginPath(); ctx.arc(x,y,21,0,Math.PI*2); ctx.fill();
    ctx.strokeStyle = "#ffffff"; ctx.fillStyle = "#ffffff"; ctx.lineWidth = 2.5; ctx.lineCap = "round";
    if (type === "phone") { ctx.font="bold 24px Arial"; ctx.textAlign="center"; ctx.textBaseline="middle"; ctx.fillText("☎",x,y); }
    else if (type === "email") { ctx.beginPath(); ctx.rect(x-12,y-8,24,16); ctx.stroke(); ctx.beginPath(); ctx.moveTo(x-12,y-7); ctx.lineTo(x,y+2); ctx.lineTo(x+12,y-7); ctx.stroke(); }
    else if (type === "pin") { ctx.beginPath(); ctx.arc(x,y-3,8,0,Math.PI*2); ctx.stroke(); ctx.beginPath(); ctx.moveTo(x-6,y+3); ctx.lineTo(x,y+13); ctx.lineTo(x+6,y+3); ctx.stroke(); ctx.beginPath(); ctx.arc(x,y-3,2,0,Math.PI*2); ctx.fill(); }
    else { ctx.beginPath(); ctx.arc(x,y,12,0,Math.PI*2); ctx.stroke(); ctx.beginPath(); ctx.ellipse(x,y,5,12,0,0,Math.PI*2); ctx.stroke(); ctx.beginPath(); ctx.moveTo(x-11,y); ctx.lineTo(x+11,y); ctx.stroke(); }
    ctx.restore();
}
function draw() {
    // O canvas exporta em 4K, mas a composição usa coordenadas lógicas 1920 × 600.
    ctx.setTransform(1,0,0,1,0,0);
    ctx.clearRect(0,0,canvas.width,canvas.height);
    ctx.setTransform(2,0,0,2,0,0);

    // Fotografia panorâmica de milho, inspirada na linha de produtos do Moinho Régio.
    ctx.fillStyle = "#fff8e8";
    ctx.fillRect(0,0,1920,600);
    if (background.complete && background.naturalWidth) {
        ctx.drawImage(background, 0, 0, 1920, 600);
        ctx.fillStyle = "rgba(55, 27, 9, 0.12)";
        ctx.fillRect(0,0,1920,600);
    }

    // Painel translúcido para garantir leitura sem esconder a fotografia.
    ctx.save();
    ctx.shadowColor = "rgba(50, 24, 8, 0.20)";
    ctx.shadowBlur = 22;
    ctx.shadowOffsetY = 7;
    ctx.fillStyle = "rgba(255, 248, 232, 0.88)";
    ctx.beginPath(); ctx.roundRect(26,28,1410,544,28); ctx.fill();
    ctx.restore();
    ctx.strokeStyle = "rgba(204, 139, 36, 0.88)";
    ctx.lineWidth = 2.5;
    ctx.beginPath(); ctx.roundRect(26,28,1410,544,28); ctx.stroke();

    // Cartão claro próprio para o selo, mantendo o destaque visual.
    ctx.save();
    ctx.shadowColor = "rgba(50, 24, 8, 0.22)";
    ctx.shadowBlur = 22;
    ctx.shadowOffsetY = 7;
    ctx.fillStyle = "rgba(255, 248, 232, 0.94)";
    ctx.beginPath(); ctx.roundRect(1470,50,420,500,26); ctx.fill();
    ctx.restore();
    ctx.strokeStyle = "rgba(204, 139, 36, 0.9)";
    ctx.lineWidth = 2.5;
    ctx.beginPath(); ctx.roundRect(1470,50,420,500,26); ctx.stroke();

    // Logo e identificação à esquerda.
    if (logo.complete && logo.naturalWidth) {
        const maxW=490, maxH=275, ratio=Math.min(maxW/logo.naturalWidth,maxH/logo.naturalHeight);
        const w=logo.naturalWidth*ratio, h=logo.naturalHeight*ratio;
        ctx.drawImage(logo, (560-w)/2, 36+(maxH-h)/2, w, h);
    }
    ctx.fillStyle="#4b170f"; ctx.textAlign="left"; ctx.textBaseline="alphabetic";
    const name=get("name"); const ns=fitText(name,520,58,34,"bold");
    ctx.font=`bold ${ns}px Arial`; ctx.fillText(name,58,390,520);
    const role=get("role"); const rs=fitText(role,520,39,27,"normal");
    ctx.fillStyle="#bd762b"; ctx.font=`${rs}px Arial`; ctx.fillText(role,58,445,520);
    ctx.fillStyle="#d99a25"; ctx.fillRect(58,472,500,6);

    // Divisória entre marca e contatos.
    ctx.fillStyle="#c98b24"; ctx.fillRect(590,62,5,470);

    // Informações de contato em coluna.
    const address=[get("address"), get("cep") ? `CEP: ${get("cep")}` : ""].filter(Boolean).join(" - ");
    const rows=[
      ["phone",get("phone")], ["email",get("email")], ["pin",address], ["pin",get("city")], ["web",get("website")]
    ].filter(row=>row[1]);
    let y=125;
    rows.forEach(([type,value])=>{
        drawIcon(type,665,y-7);
        ctx.fillStyle="#56331f"; ctx.textAlign="left"; ctx.textBaseline="middle";
        const fs=fitText(value,690,34,21,"normal"); ctx.font=`${fs}px Arial`;
        ctx.fillText(value,710,y,690); y+=88;
    });

    // Divisória antes do selo.
    ctx.fillStyle="#c98b24"; ctx.fillRect(1450,62,5,470);

    // Selo ampliado à direita, preservando a proporção.
    if (seal.complete && seal.naturalWidth) {
        const maxW=340,maxH=450,ratio=Math.min(maxW/seal.naturalWidth,maxH/seal.naturalHeight);
        const w=seal.naturalWidth*ratio,h=seal.naturalHeight*ratio;
        ctx.drawImage(seal,1510+(340-w)/2,(600-h)/2,w,h);
    }
}
function fiftyEight() { return 58; }
function downloadPNG() {
    draw();
    canvas.toBlob(blob=>{
        if(!blob){alert("Não foi possível gerar a imagem.");return;}
        const url=URL.createObjectURL(blob), link=document.createElement("a");
        link.href=url; link.download="assinatura-moinho-regio-milho-4k.png";
        document.body.appendChild(link); link.click(); link.remove(); setTimeout(()=>URL.revokeObjectURL(url),1000);
    },"image/png");
}
document.querySelectorAll("input").forEach(input=>input.addEventListener("input",draw));
document.getElementById("download").addEventListener("click",downloadPNG);
window.addEventListener("resize",draw);
if (logo.complete && seal.complete) draw();
